WITH cleaned AS (SELECT *, HOUR(txn_time) txn_time_hour FROM transactions WHERE txn_time > TO_DATE('2023-05-27') AND is_flagged), cleaned_transactions AS (SELECT *, HOUR(txn_time) txn_time_hour_2 FROM cleaned WHERE txn_time >= DATE '2023-08-04'), gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM cleaned_transactions), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), metrics AS (SELECT *, LAST_VALUE(txn_time_hour) IGNORE NULLS OVER w_running last_known_txn_time_hour, SUM(amount) OVER w_ordered running_amount, NTILE(5) OVER w_running_2 txn_time_hour_bucket, LAST_VALUE(amount) IGNORE NULLS OVER (ORDER BY txn_time_hour, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_amount FROM islands WHERE is_new_burst = 1 WINDOW w_running AS (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered AS (PARTITION BY txn_type, merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running_2 AS (PARTITION BY merchant, account_id ORDER BY txn_time_hour, id)), deduped AS (SELECT id, account_id, txn_time, merchant, is_new_burst, burst_id, last_known_txn_time_hour, running_amount, last_known_amount FROM metrics QUALIFY ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY is_new_burst, id) = 1) SELECT s.id, s.account_id, s.txn_time, s.burst_id, s.last_known_txn_time_hour, s.running_amount, s.last_known_amount, (SELECT MIN(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS min_transaction_amount FROM deduped s ORDER BY running_amount
